~/.claude/skills/taskbar-icons/scripts/icon-set --list 2>/dev/null | tr '\n' ' '; echo; echo; pkgs=$(sed 's/#.*//' /usr/share/omarchy/install/omarchy-*.packages | tr -s ' \t' '\n' | sort -u); for p in $pkgs; do pacman -Qlq $p 2>/dev/null | grep -E '^/usr/share/applications/[^/]+\.desktop$'; done | sort -u | while read f; do nd=$(grep -m1 -i '^NoDisplay=true' "$f"); [[ -n $nd ]] && continue; echo "$(basename $f .desktop) | $(grep -m1 '^Name=' $f | cut -d= -f2) | wm=$(grep -m1 '^StartupWMClass=' $f | cut -d= -f2) | exec=$(grep -m1 '^Exec=' $f | cut -d= -f2 | cut -c1-40)"; done
